/**
 * Passes that draw a scene's meshes besides the camera's own, each asked
 * whether it can draw a mesh yet. A pass that cannot skips the mesh, and
 * leaves a hole in what it draws: the clouds' ground depth without a tile
 * reads as open sky there, and the clouds are drawn black over it. Asking
 * also builds what the pass draws the mesh with, so a mesh can be held back
 * until every pass is ready for it.
 */

import type { AbstractMesh } from '@babylonjs/core/Meshes/abstractMesh';
import type { Scene } from '@babylonjs/core/scene';

export type MeshReadyCheck = (mesh: AbstractMesh) => boolean;

const checks = new WeakMap<Scene, Set<MeshReadyCheck>>();

/** Adds a pass's check to the scene's; the function returned takes it away. */
export function addMeshReadyCheck(scene: Scene, check: MeshReadyCheck): () => void {
  let set = checks.get(scene);
  if (!set) checks.set(scene, (set = new Set()));
  set.add(check);
  return () => void set.delete(check);
}

/** Whether every pass the scene has added can draw the mesh. Each is asked, so each builds what it needs. */
export function meshReadyInEveryPass(scene: Scene, mesh: AbstractMesh): boolean {
  let ready = true;
  for (const check of checks.get(scene) ?? []) if (!check(mesh)) ready = false;
  return ready;
}
