/**
 * A planet's clouds: layers in its air, as the world sets them. How much of
 * the sky they cover, how high they float and how thick, how wide a cloud is, how fast the
 * wind carries them around the planet and their colour in full sun are the
 * world's; for what a world leaves unsaid, the shell's defaults below. Where
 * the clouds are is a smooth noise over the layer; how bright they are
 * follows the sun's height over them.
 *
 * This is the reference the clouds' shader (cloudChunk.ts) follows, on the
 * processor. The noise uses the same hash and constants as the shader, so the
 * two agree in kind, though not to the last bit: the card sums in 32 bits.
 */
import type { Atmosphere, Vec3 } from './atmosphere';

/** What a world says of its clouds; anything left out is the shell's default. */
export interface CloudSettings {
  /** The share of the sky covered, 0 to 1. */
  cover: number;
  /** Metres over altitude 0. */
  altitude?: number;
  /** Metres across a cloud, about. */
  size?: number;
  /** Metres a second the clouds drift eastward around the planet's axis; negative is westward. */
  wind?: number;
  /** Their colour in full sun, red, green and blue, 0 to 1. */
  color?: Vec3;
  /** How much of the sky behind its thickest cloud the layer hides, 0 to 1. */
  opacity?: number;
  /** How much of the sun's direct light its thickest cloud keeps from the ground, 0 to 1. */
  shadow?: number;
  /** Metres from the layer's base to its top, where it is drawn as a volume. */
  thickness?: number;
  /** How much the clouds' bases rise and fall from cloud to cloud, 0 (one level base) to 1. */
  baseVariety?: number;
}

export interface CloudLayer {
  cover: number;
  altitude: number;
  /** Metres from the planet's centre to the layer. */
  radius: number;
  size: number;
  wind: number;
  color: Vec3;
  opacity: number;
  shadow: number;
  /** Metres from `altitude` (the base) to the layer's top. */
  thickness: number;
  /** How much the clouds' bases rise and fall from cloud to cloud, 0 to 1. */
  baseVariety: number;
}

/** The shell's defaults for what a world does not say, for its lowest layer: heaped cloud, some seven hundred metres thick. */
export const CLOUD_DEFAULTS = { cover: 0.4, size: 2500, wind: 8, color: [1, 1, 1] as Vec3, opacity: 0.92, shadow: 0.65, thickness: 700, baseVariety: 0.8 };
/**
 * The shell's defaults for a higher layer: thin high cloud, as Earth's
 * cirrus is over its heaped cloud, wider, faster, fainter, thin and casting
 * little shadow.
 */
const HIGH_DEFAULTS = { cover: 0.2, size: 7000, wind: 20, color: [1, 1, 1] as Vec3, opacity: 0.45, shadow: 0.15, thickness: 150, baseVariety: 0.8 };
/** Where the shell puts a layer the world gives no height: the lowest at a sixth of the air's height and no higher than 1.2 km, the others at under half of it and no higher than 6 km. */
const lowAltitude = (a: Atmosphere) => Math.min(800, 0.1 * a.top);
const highAltitude = (a: Atmosphere) => Math.min(4500, 0.35 * a.top);
/** Layers a world that leaves them to the shell gets. */
export const CLOUD_LAYER_COUNT = 2;
/** Layers of noise summed, each twice as fine and half as strong. */
export const CLOUD_OCTAVES = 5;
/** How far the noise strays from its middle (0.5) for a share of cover: the layers' sum is narrower than 0 to 1. */
const SPREAD = 0.34;
/** How soft a cloud's edge is, in noise. */
const EDGE = 0.06;
/** The highest a layer floats, as a share of its air's height: clouds stay in the air. */
const HIGHEST = 0.9;

/** The numbers the shader must carry as the reference does, written as it writes them. */
export const CLOUD_CONSTANTS = ['0.1031', '31.32', '0.34', '0.06'] as const;

/** How much finer the detail that tears a volume's edges is than a cloud, and how deep it bites. */
const DETAIL_SCALE = 8.3;
const DETAIL_EROSION = 0.45;
/** How far, as a share of the shell, the detail lowers a column's top in places: the heaps on heaped cloud. */
const TOP_BUMPS = 0.25;
/** Layers of noise in a volume's base shape (its outline, the fine edge left to the detail), and in the detail. */
const VOLUME_BASE_OCTAVES = 4;
const VOLUME_DETAIL_OCTAVES = 3;
/**
 * The numbers the volume's shader must carry: the detail's scale and bite,
 * the light scattered forward and back (Henyey-Greenstein, 0.62 and -0.24),
 * how much light a metre of the densest cloud takes out (0.015), and how far
 * the detail lowers a column's top (0.25).
 */
export const CLOUD_VOLUME_CONSTANTS = ['8.3', '0.45', '0.62', '0.24', '0.015', '0.25 * n'] as const;

/**
 * A cloud's base: how coarse the noise that sets each cloud's own level is
 * (as a share of the clouds' noise, so one cloud lies mostly within one of its
 * cells and its base is about level), where it is read from (away from the
 * clouds' own, so the two do not line up), the most a base rises as a share
 * of the shell at full variety, and how much less a cloud's thick middle rises
 * than its edge (the droop).
 */
const BASE_SCALE = 0.7;
const BASE_OFFSET = 41.7;
const BASE_LIFT = 0.45;
const BASE_DROOP = 0.4;
/** How dark a flat cloud's thick middle is from under it, and how much its base's level adds or takes away. */
const UNDER_DARK = 0.3;
const UNDER_VARIETY = 0.4;
/** The numbers the shaders must carry for the base, written as they write them. */
export const CLOUD_BASE_CONSTANTS = ['0.7', '41.7', '0.45', '0.4 * c', '0.3 + 0.4'] as const;

/** The clouds a world asks for, in its air: by default low in it, at a sixth of its height and no higher than 1.2 km. */
export function cloudLayerOf(a: Atmosphere, s: CloudSettings): CloudLayer {
  return layerOf(a, s, CLOUD_DEFAULTS, lowAltitude(a));
}

/**
 * The layers a world asks for, lowest first: one for each entry, each with
 * the world's values where it gave them and the shell's for the rest (the
 * lowest layer's defaults for the first, a high layer's for the others).
 */
export function cloudLayersOf(a: Atmosphere, layers: Partial<CloudSettings>[]): CloudLayer[] {
  return layers.map((s, i) =>
    i === 0
      ? layerOf(a, { cover: CLOUD_DEFAULTS.cover, ...s }, CLOUD_DEFAULTS, lowAltitude(a))
      : layerOf(a, { cover: HIGH_DEFAULTS.cover, ...s }, HIGH_DEFAULTS, highAltitude(a)),
  );
}

function layerOf(a: Atmosphere, s: CloudSettings, d: typeof CLOUD_DEFAULTS, defaultAltitude: number): CloudLayer {
  const altitude = Math.min(Math.max(s.altitude ?? defaultAltitude, 0), HIGHEST * a.top);
  // However thick it is asked to be, the layer's top stays in the air.
  const thickness = Math.max(0, Math.min(s.thickness ?? d.thickness, HIGHEST * a.top - altitude));
  return {
    cover: Math.min(1, Math.max(0, s.cover)),
    altitude,
    radius: a.radius + altitude,
    size: s.size ?? d.size,
    wind: s.wind ?? d.wind,
    color: s.color ?? d.color,
    opacity: Math.min(1, Math.max(0, s.opacity ?? d.opacity)),
    shadow: Math.min(1, Math.max(0, s.shadow ?? d.shadow)),
    thickness,
    baseVariety: Math.min(1, Math.max(0, s.baseVariety ?? d.baseVariety)),
  };
}

/**
 * How much of the sun's direct light reaches `point` (metres from the
 * planet's centre, in its frame) through the layers over it, toward the unit
 * `sun`, at `timeS` seconds: 1 in full sun. Each layer the light crosses
 * keeps its `shadow` share where its cloud is thickest, along the sun's ray,
 * not straight up; a layer under the point keeps nothing.
 */
export function cloudShadow(layers: CloudLayer[], point: Vec3, sun: Vec3, timeS: number, octaves = CLOUD_OCTAVES): number {
  let light = 1;
  const pp = point[0] * point[0] + point[1] * point[1] + point[2] * point[2];
  const b = point[0] * sun[0] + point[1] * sun[1] + point[2] * sun[2];
  for (const layer of layers) {
    if (layer.shadow <= 0 || pp >= layer.radius * layer.radius) continue;
    // Where the ray toward the sun leaves the layer's sphere, from inside it.
    const t = -b + Math.sqrt(b * b - (pp - layer.radius * layer.radius));
    const hit: Vec3 = [point[0] + sun[0] * t, point[1] + sun[1] * t, point[2] + sun[2] * t];
    const l = Math.hypot(...hit);
    light *= 1 - layer.shadow * cloudDensity(layer, [hit[0] / l, hit[1] / l, hit[2] / l], timeS, octaves);
  }
  return light;
}

const fract = (x: number) => x - Math.floor(x);
/** A hash of a lattice point, 0 to 1, without `sin` (whose precision on a graphics card fails for large arguments). */
const hash = (x: number, y: number, z: number) => {
  let a = fract(x * 0.1031), b = fract(y * 0.1031), c = fract(z * 0.1031);
  const d = a * (c + 31.32) + b * (b + 31.32) + c * (a + 31.32);
  a += d; b += d; c += d;
  return fract((a + b) * c);
};
const fade = (t: number) => t * t * (3 - 2 * t);

function valueNoise(x: number, y: number, z: number): number {
  const ix = Math.floor(x), iy = Math.floor(y), iz = Math.floor(z);
  const fx = fade(x - ix), fy = fade(y - iy), fz = fade(z - iz);
  const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
  const c = (dx: number, dy: number, dz: number) => hash(ix + dx, iy + dy, iz + dz);
  return lerp(
    lerp(lerp(c(0, 0, 0), c(1, 0, 0), fx), lerp(c(0, 1, 0), c(1, 1, 0), fx), fy),
    lerp(lerp(c(0, 0, 1), c(1, 0, 1), fx), lerp(c(0, 1, 1), c(1, 1, 1), fx), fy),
    fz,
  );
}

/** The layers of noise at a point, 0 to 1, about 0.5 on average. */
export function cloudNoise(x: number, y: number, z: number, octaves = CLOUD_OCTAVES): number {
  let sum = 0, weight = 0, amp = 1, f = 1;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * f, y * f, z * f);
    weight += amp;
    amp *= 0.5;
    f *= 2;
  }
  return sum / weight;
}

const smoothstep = (e0: number, e1: number, x: number) => {
  const t = Math.min(1, Math.max(0, (x - e0) / (e1 - e0)));
  return t * t * (3 - 2 * t);
};

/**
 * The cover at a point, 0 to 1: the layers of noise there, eased from `lo`
 * (clear) to `hi` (full cloud), exactly as `cloudNoise` would give them; and
 * how many octaves it took. Each noise lies in 0 to 1, so the sum stops once
 * even the octaves left at their most could not lift it over `lo`, or at
 * their least bring it under `hi`: clear air and the thick of a cloud, most of
 * the sky, cost the shader fewer octaves for the same answer.
 */
export function cloudCoverNoise(x: number, y: number, z: number, octaves: number, lo: number, hi: number): { cover: number; octaves: number } {
  let total = 0;
  for (let i = 0, a = 1; i < octaves; i++, a *= 0.5) total += a;
  let sum = 0, weight = 0, amp = 1, f = 1;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * f, y * f, z * f);
    weight += amp;
    amp *= 0.5;
    f *= 2;
    const rest = total - weight;
    if (sum + rest < lo * total) return { cover: 0, octaves: i + 1 };
    if (sum > hi * total) return { cover: 1, octaves: i + 1 };
  }
  return { cover: smoothstep(lo, hi, sum / total), octaves };
}

/** What the world may ask of how finely the volume is marched (`planet.cloud-detail`), as a share of the screen's width and height. */
const CLOUD_DETAIL: Record<string, number> = { full: 1, half: 0.5, quarter: 0.25 };

/** The share of the screen's width and height the volume is marched at: the world's `full`, `half` or `quarter`, or for anything else the tier's. */
export function cloudScaleOf(tierScale: number, asked: unknown): number {
  return typeof asked === 'string' && asked in CLOUD_DETAIL ? CLOUD_DETAIL[asked]! : tierScale;
}

/**
 * The farthest ground depth, in metres, that the ground's depth map tells
 * apart from its limit: it is kept in half floats where the card draws them,
 * which top out at 65504 m. Past it the ground could be anywhere, so it hides
 * no cloud.
 */
export const CLOUD_DEPTH_TRUSTED_M = 60000;

/**
 * Whether the march may pass over a pixel of its target: the ground's
 * camera-space depths at that pixel and the eight around it (0 where nothing
 * was drawn, the sky) all stand in front of where the eye's line enters the
 * shell, `shellZ` ahead of the camera. The lay-over reads a pixel of the
 * target only for the screen's pixels around it, so where all nine are ground
 * no pixel of sky reads what was passed over. A depth at or past
 * CLOUD_DEPTH_TRUSTED_M says nothing of where the ground is, and never hides.
 */
export function cloudHiddenByGround(depths: readonly number[], shellZ: number): boolean {
  for (const z of depths) if (z <= 0 || z >= shellZ || z >= CLOUD_DEPTH_TRUSTED_M) return false;
  return true;
}

/** The size of the target the volume is marched into, for a screen `width` by `height` and a share `scale`: rounded up, never under a pixel. */
export function cloudTargetSize(width: number, height: number, scale: number): { width: number; height: number } {
  return { width: Math.max(1, Math.ceil(width * scale)), height: Math.max(1, Math.ceil(height * scale)) };
}

/**
 * How much cloud lies over the unit direction `dir` from the planet's centre
 * (in its frame, +y the north pole) at `timeS` seconds: 0 clear, 1 cloud.
 * The wind turns the pattern eastward about the axis, so the cloud over a
 * place now was over a place to its west before.
 */
export function cloudDensity(layer: CloudLayer, dir: Vec3, timeS: number, octaves = CLOUD_OCTAVES): number {
  if (layer.cover <= 0) return 0;
  if (layer.cover >= 1) return 1;
  // Longitude grows toward +z from +x (planetFrame), so eastward is a turn from +x toward +z.
  const turn = (timeS * layer.wind) / layer.radius;
  const c = Math.cos(turn), s = Math.sin(turn);
  const x = dir[0] * c + dir[2] * s;
  const z = dir[2] * c - dir[0] * s;
  const k = layer.radius / layer.size;
  const threshold = 0.5 + (0.5 - layer.cover) * SPREAD;
  return cloudCoverNoise(x * k, dir[1] * k, z * k, octaves, threshold - EDGE, threshold + EDGE).cover;
}

/**
 * Where the cloud over the unit direction `dir` (planet frame) begins, as a
 * share of the layer's shell over its altitude, at `timeS` seconds, for cloud
 * `c` thick there (the layer's density; worked out when not given). Each
 * cloud has its own level, from a coarse noise carried by the same wind, so
 * bases differ from cloud to cloud but are about level within one; a cloud's
 * thick middle droops below its edge. With no variety, every base is 0.
 */
export function cloudBaseOf(layer: CloudLayer, dir: Vec3, timeS: number, c = cloudDensity(layer, dir, timeS)): number {
  if (layer.baseVariety <= 0) return 0;
  const turn = (timeS * layer.wind) / layer.radius;
  const cs = Math.cos(turn), sn = Math.sin(turn);
  const k = (layer.radius / layer.size) * BASE_SCALE;
  const m = valueNoise((dir[0] * cs + dir[2] * sn) * k + BASE_OFFSET, dir[1] * k + BASE_OFFSET, (dir[2] * cs - dir[0] * sn) * k + BASE_OFFSET);
  return layer.baseVariety * BASE_LIFT * smoothstep(0.25, 0.75, m) * (1 - BASE_DROOP * c);
}

/**
 * How much of its light a flat layer's cloud over `dir` shows from under it,
 * 0 to 1: its thick middle darker, and a cloud whose base lies lower (by the
 * same base the volume rises from) darker beneath than one whose base is high.
 */
export function cloudUnderside(layer: CloudLayer, dir: Vec3, timeS: number, octaves = CLOUD_OCTAVES): number {
  const c = cloudDensity(layer, dir, timeS, octaves);
  const lift = layer.baseVariety > 0 ? cloudBaseOf(layer, dir, timeS, c) / (layer.baseVariety * BASE_LIFT) : 0.5;
  return 1 - c * c * (UNDER_DARK + UNDER_VARIETY * layer.baseVariety * (0.5 - lift));
}

/**
 * How dense the cloud is at `point` (metres from the planet's centre, in its
 * frame) at `timeS` seconds, 0 to 1, where the layer is drawn as a volume:
 * none outside its shell, between its base and its top. Over a place, cloud
 * rises from its base (cloudBaseOf) as high as the layer's cover there is strong, so
 * heaped cloud stands tallest at its middle and thins toward its top; and a
 * finer noise, carried by the same wind, tears its edges.
 */
export function cloudVolumeDensity(layer: CloudLayer, point: Vec3, timeS: number): number {
  if (layer.cover <= 0 || layer.thickness <= 0) return 0;
  const r = Math.hypot(...point);
  const h = (r - layer.radius) / layer.thickness;
  if (h < 0 || h > 1) return 0;
  const dir: Vec3 = [point[0] / r, point[1] / r, point[2] / r];
  const c = cloudDensity(layer, dir, timeS, VOLUME_BASE_OCTAVES);
  if (c <= 0) return 0;
  // The column stands from its own base to the shell's top, its shape squeezed to fit.
  const b = cloudBaseOf(layer, dir, timeS, c);
  const hc = (h - b) / (1 - b);
  if (hc < 0) return 0;
  const turn = (timeS * layer.wind) / layer.radius;
  const cs = Math.cos(turn), sn = Math.sin(turn);
  const k = DETAIL_SCALE / layer.size;
  const n = cloudNoise((point[0] * cs + point[2] * sn) * k, point[1] * k, (point[2] * cs - point[0] * sn) * k, VOLUME_DETAIL_OCTAVES);
  // The detail heaps the tops unevenly and tears the edges.
  const top = 0.25 + 0.75 * c - TOP_BUMPS * n;
  const base = c * smoothstep(0, 0.07, hc) * (1 - smoothstep(top - 0.25, top, hc));
  if (base <= 0) return 0;
  return Math.min(1, Math.max(0, (base - n * DETAIL_EROSION) / (1 - DETAIL_EROSION)));
}

/** The most steps the volume's shader takes along the eye's line, whatever its budget. */
export const CLOUD_MARCH_MAX_STEPS = 168;

/**
 * The steps the volume's shader takes along the eye's line through a layer's
 * shell, from `t0` to `t1` metres along it, as it takes them, until it first
 * finds cloud: long strides through clear air, and once a stride lands in
 * cloud, back a stride and short steps through it, leaving it after a few
 * short steps in a row past where the stride found it find none. `density(t)`
 * is the cloud at `t` metres along the line; `jitter`, 0 to 1, how far into
 * the first stride the march starts; `budget` the most steps it may take.
 * Gives where a short step first found cloud (-1 if none did) and how many
 * steps it took.
 */
export function cloudMarch(
  t0: number,
  t1: number,
  opts: { steps: number; thickness: number; jitter: number; budget: number },
  density: (t: number) => number,
): { firstHit: number; used: number } {
  const coarse = Math.min(800, Math.max(50, (t1 - t0) / opts.steps));
  const fine = Math.min(200, Math.max(15, (opts.thickness * 1.2) / opts.steps));
  let t = t0 + coarse * opts.jitter;
  let inCloud = false;
  let clearRun = 0;
  let found = t0;
  for (let i = 0; i < CLOUD_MARCH_MAX_STEPS; i++) {
    if (i >= opts.budget || t > t1) return { firstHit: -1, used: i };
    const dens = density(t);
    // Four short steps at the eye, longer by a twentieth of the way gone: a longer stride near the eye steps over a
    // grazed thin cloud top for some pixels' starts and not others, dotting its outline with the shaded cloud behind.
    const stride = Math.min(coarse, fine * 4 + (t - t0) * 0.05);
    if (!inCloud) {
      if (dens <= 0.003) { t += stride; continue; }
      inCloud = true;
      clearRun = 0;
      found = t;
      t = Math.max(t - stride, t0);
      continue;
    }
    if (dens <= 0.003) {
      // Clear air short of where the stride found cloud does not count toward leaving it.
      if (t > found) clearRun += 1;
      if (clearRun > 4) inCloud = false;
    } else {
      return { firstHit: t, used: i + 1 };
    }
    t += fine;
  }
  return { firstHit: -1, used: CLOUD_MARCH_MAX_STEPS };
}

/**
 * The light on a cloud of colour `color`, red, green and blue, 0 to 1, with
 * the sun `sunUp` over its horizon (the sine of its height there): the colour
 * by day, warmer as the sun sets, a dim grey by night.
 */
export function cloudLight(sunUp: number, color: Vec3 = CLOUD_DEFAULTS.color): Vec3 {
  const day = smoothstep(-0.1, 0.2, sunUp);
  const warm = 1 - smoothstep(0, 0.3, sunUp);
  const night: Vec3 = [0.12, 0.13, 0.17];
  const tint: Vec3 = [1, 0.62, 0.42];
  return [0, 1, 2].map((k) => {
    const lit = night[k]! + (color[k]! - night[k]!) * day;
    return lit * (1 - warm * (1 - tint[k]!));
  }) as Vec3;
}
